        "id": "fb064b76-4358-11ef-0a80-114b000d5963",
        "name": "Ajmal Wisal (жен)",
        "code": "0_0180 LZ",
        "article": "0_0180 LZ",
        "quantity": null,
        "vip": 33,
        "vip10": 33,
        "vip25": 33,
